   265    struct matcher_t
   266    {
   267      inline matcher_t (void) :
   268               lookup_props (0),
   269               ignore_zwnj (false),
   270               ignore_zwj (false),
   271               mask (-1),
   272  #define arg1(arg) (arg) /* Remove the macro to see why it's needed! */
   273               syllable arg1(0),
   274  #undef arg1
   275               match_func (nullptr),
   276               match_data (nullptr) {};
   277
   278      typedef bool (*match_func_t) (hb_codepoint_t glyph_id, const HBUINT16 &value, const void *data);
   279
   280      inline void set_ignore_zwnj (bool ignore_zwnj_) { ignore_zwnj = ignore_zwnj_; }
   281      inline void set_ignore_zwj (bool ignore_zwj_) { ignore_zwj = ignore_zwj_; }
   282      inline void set_lookup_props (unsigned int lookup_props_) { lookup_props = lookup_props_; }
   283      inline void set_mask (hb_mask_t mask_) { mask = mask_; }
   284      inline void set_syllable (uint8_t syllable_)  { syllable = syllable_; }
   285      inline void set_match_func (match_func_t match_func_,
   286                                  const void *match_data_)
   287      { match_func = match_func_; match_data = match_data_; }
   288
   289      enum may_match_t {
   290        MATCH_NO,
   291        MATCH_YES,
   292        MATCH_MAYBE
   293      };
   294
   295      inline may_match_t may_match (const hb_glyph_info_t &info,
   296                                    const HBUINT16          *glyph_data) const
   297      {
   298        if (!(info.mask & mask) ||
   299            (syllable && syllable != info.syllable ()))
   300          return MATCH_NO;
   301
   302        if (match_func)
   303          return match_func (info.codepoint, *glyph_data, match_data) ? MATCH_YES : MATCH_NO;
   304
   305        return MATCH_MAYBE;
   306      }
   307
   308      enum may_skip_t {
   309        SKIP_NO,
   310        SKIP_YES,
   311        SKIP_MAYBE
   312      };
   313
   314      inline may_skip_t
   315      may_skip (const hb_ot_apply_context_t *c,
   316                const hb_glyph_info_t    &info) const
   317      {
   318        if (!c->check_glyph_property (&info, lookup_props))
   319          return SKIP_YES;
   320
   321        if (unlikely (_hb_glyph_info_is_default_ignorable_and_not_hidden (&info) &&
   322                      (ignore_zwnj || !_hb_glyph_info_is_zwnj (&info)) &&
   323                      (ignore_zwj || !_hb_glyph_info_is_zwj (&info))))
   324          return SKIP_MAYBE;
   325
   326        return SKIP_NO;
   327      }
   328
   329      protected:
   330      unsigned int lookup_props;
   331      bool ignore_zwnj;
   332      bool ignore_zwj;
   333      hb_mask_t mask;
   334      uint8_t syllable;
   335      match_func_t match_func;
   336      const void *match_data;
