554    check_glyph_property (const hb_glyph_info_t *info,
   555                          unsigned int  match_props) const
   556    {
   557      hb_codepoint_t glyph = info->codepoint;
   558      unsigned int glyph_props = _hb_glyph_info_get_glyph_props (info);
   559
   560      /* Not covered, if, for example, glyph class is ligature and
   561       * match_props includes LookupFlags::IgnoreLigatures
   562       */
   563      if (glyph_props & match_props & LookupFlag::IgnoreFlags)
   564        return false;
   565
   566      if (unlikely (glyph_props & HB_OT_LAYOUT_GLYPH_PROPS_MARK))
   567        return match_properties_mark (glyph, glyph_props, match_props);
   568
   569      return true;
